class Solution {
    public int countStudents(int[] students,int[] sandwiches){
        int[] count=new int[2];
        for(int student:students)count[student]++;
        for(int i=0;i<sandwiches.length;i++){
            int type=sandwiches[i];
            if(count[type]==0)return sandwiches.length-i;
            count[type]--;
        }
        return 0;
    }
}

code.kotlin:
class Solution {
    fun countStudents(students:IntArray,sandwiches:IntArray):Int{
        val count=IntArray(2);
        for(student in students)count[student]++;
        for(i in sandwiches.indices){
            val type=sandwiches[i];
            if(count[type]==0)return sandwiches.size-i;
            count[type]--
        };
        return 0
    }
}

